package org.eclipse.kura.core.keystore;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assume.assumeTrue;
import static org.mockito.AdditionalMatchers.aryEq;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doThrow;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.FileSystems;
import java.nio.file.Files;
import java.nio.file.attribute.PosixFilePermissions;
import java.security.KeyStore;
import java.security.KeyStore.TrustedCertificateEntry;
import java.util.HashMap;
import java.util.Map;

import org.eclipse.kura.KuraErrorCode;
import org.eclipse.kura.KuraException;
import org.junit.Test;

public class AtomicKeystoreSaveTest extends AbstractFilesystemKeystoreServiceTest {

    private static final String NEW_PASSWORD = "newpass";

    @Test
    public void savesAddedEntry() throws Exception {
        givenKeystoreWithCertificate("existing");
        givenActivatedKeystoreService();

        whenCertificateIsAdded("added");

        thenNoExceptionIsThrown();
        thenKeystoreFileContainsOnly(KEYSTORE_NAME, PASSWORD, "existing", "added");
        thenDirectoryContainsOnly(KEYSTORE_NAME);
    }

    @Test
    public void leavesKeystoreUnchangedWhenSaveFails() throws Exception {
        givenKeystoreWithCertificate("existing");
        givenKeystoreMoveFails();
        givenActivatedKeystoreService();

        whenCertificateIsAdded("added");

        thenKuraExceptionIsThrown();
        thenKeystoreFileContainsOnly(KEYSTORE_NAME, PASSWORD, "existing");
        thenDirectoryContainsOnly(KEYSTORE_NAME);
    }

    @Test
    public void leavesNoCopyWithOldPasswordWhenPasswordChanges() throws Exception {
        givenKeystoreWithCertificate("existing");
        givenActivatedKeystoreService();

        whenKeystorePasswordIsChangedTo(NEW_PASSWORD);

        thenNoExceptionIsThrown();
        thenKeystoreFileContainsOnly(KEYSTORE_NAME, NEW_PASSWORD, "existing");
        thenNoFileOpensWith(PASSWORD);
    }

    @Test
    public void leavesNoCopyWithOldPasswordWhenNewPasswordIsNotPersisted() throws Exception {
        givenKeystoreWithCertificate("existing");
        givenNewPasswordCannotBePersisted();
        givenActivatedKeystoreService();

        whenKeystorePasswordIsChangedTo(NEW_PASSWORD);

        thenNoExceptionIsThrown();
        thenKeystoreFileContainsOnly(KEYSTORE_NAME, NEW_PASSWORD, "existing");
        thenNoFileOpensWith(PASSWORD);
    }

    @Test
    public void createsNewKeystoreWithOwnerOnlyPermissions() throws Exception {
        givenPosixFileSystem();

        whenKeystoreServiceIsActivated();

        thenNoExceptionIsThrown();
        thenKeystoreFileContainsOnly(KEYSTORE_NAME, PASSWORD);
        thenKeystoreHasPermissions("rw-------");
    }

    @Test
    public void leavesNoKeystoreWhenCreationFails() {
        givenKeystoreMoveFails();

        whenKeystoreServiceIsActivated();

        thenDirectoryContainsOnly();
    }

    private void givenPosixFileSystem() {
        assumeTrue(FileSystems.getDefault().supportedFileAttributeViews().contains("posix"));
    }

    private void givenNewPasswordCannotBePersisted() throws KuraException {
        doThrow(new KuraException(KuraErrorCode.INTERNAL_ERROR)).when(this.cryptoService)
                .setKeyStorePassword(anyString(), aryEq(NEW_PASSWORD.toCharArray()));
    }

    private void whenCertificateIsAdded(final String alias) {
        try {
            this.keystoreService.setEntry(alias, new TrustedCertificateEntry(readCertificate()));
        } catch (Exception e) {
            this.exception = e;
        }
    }

    private void whenKeystorePasswordIsChangedTo(final String newPassword) {
        final Map<String, Object> updatedProperties = new HashMap<>(this.properties);
        updatedProperties.put(FilesystemKeystoreServiceOptions.KEY_KEYSTORE_PASSWORD, newPassword);
        try {
            this.keystoreService.updated(updatedProperties);
        } catch (Exception e) {
            this.exception = e;
        }
    }

    private void thenNoFileOpensWith(final String password) {
        for (final File file : this.folder.getRoot().listFiles()) {
            assertFalse(file.getName() + " opens with password " + password, opensWith(file, password));
        }
    }

    private void thenKeystoreHasPermissions(final String expected) throws IOException {
        assertEquals(expected,
                PosixFilePermissions.toString(Files.getPosixFilePermissions(keystoreFile(KEYSTORE_NAME).toPath())));
    }

    private static boolean opensWith(final File file, final String password) {
        try (InputStream in = new FileInputStream(file)) {
            KeyStore.getInstance(KeyStore.getDefaultType()).load(in, password.toCharArray());
            return true;
        } catch (Exception e) {
            return false;
        }
    }
}
